/**
 * Builds the sentence data of the sentence games (DESIGN.md 5 ter) into public/data/:
 * sentences-zh.json (Tatoeba), measure-words.json (adapted from CC-CEDICT) and hsk-words.json
 * (complete-hsk-vocabulary). It never runs in the CI: the files are generated by hand, then
 * committed; the CI only checks their format and size.
 *
 * Usage (Node 26, which strips the types itself):
 *   node scripts/sentences/buildSentenceData.ts <folder of the downloaded sources> [out folder]
 *
 * The sources are listed in SOURCES below, with their URLs. Download and decompress them into
 * a folder outside the repository; their SHA-256 are written to public/data/README.md, so that a
 * later run can be checked against the same inputs. The output is deterministic: same inputs,
 * same Node (ICU) version, same files.
 */
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import * as OpenCC from 'opencc-js';
import {
  isBlockedChinese,
  isBlockedTag,
  isBlockedTranslation,
  MAINTENANCE_TAG_PREFIX,
} from './blocklist.ts';

interface Source {
  file: string;
  url: string;
}

const TATOEBA = 'https://downloads.tatoeba.org/exports/per_language';
const HSK_COMMIT = '7ac65bf1a6387d35f1ade478906172a19311c7f9';
const HSK_REPOSITORY = 'https://github.com/drkameleon/complete-hsk-vocabulary';

const SOURCES: readonly Source[] = [
  { file: 'cmn_sentences_detailed.tsv', url: `${TATOEBA}/cmn/cmn_sentences_detailed.tsv.bz2` },
  { file: 'fra_sentences_detailed.tsv', url: `${TATOEBA}/fra/fra_sentences_detailed.tsv.bz2` },
  { file: 'eng_sentences_detailed.tsv', url: `${TATOEBA}/eng/eng_sentences_detailed.tsv.bz2` },
  { file: 'cmn-fra_links.tsv', url: `${TATOEBA}/cmn/cmn-fra_links.tsv.bz2` },
  { file: 'cmn-eng_links.tsv', url: `${TATOEBA}/cmn/cmn-eng_links.tsv.bz2` },
  { file: 'cmn_sentences_CC0.tsv', url: `${TATOEBA}/cmn/cmn_sentences_CC0.tsv.bz2` },
  { file: 'cmn_tags.tsv', url: `${TATOEBA}/cmn/cmn_tags.tsv.bz2` },
  { file: 'fra_tags.tsv', url: `${TATOEBA}/fra/fra_tags.tsv.bz2` },
  { file: 'eng_tags.tsv', url: `${TATOEBA}/eng/eng_tags.tsv.bz2` },
  {
    file: 'cedict.txt',
    url: 'https://www.mdbg.net/chinese/export/cedict/cedict_1_0_ts_utf-8_mdbg.txt.gz',
  },
  ...[1, 2, 3, 4, 5, 6].map((level) => ({
    file: `hsk${String(level)}.json`,
    url: `https://raw.githubusercontent.com/drkameleon/complete-hsk-vocabulary/${HSK_COMMIT}/wordlists/exclusive/old/${String(level)}.min.json`,
  })),
];

/** The longest sentence kept, in characters (GAME_DESIGN.md 6.10). */
const MAX_CHARS = 20;
/** A sentence may hold at most this many words outside HSK 1-4 (DESIGN.md 5 ter). */
const MAX_WORDS_OUTSIDE_HSK4 = 2;
const ANONYMOUS = 'Tatoeba contributors';
/** The sentence bank must stay small enough to download on a phone (DESIGN.md 5 ter). */
const TARGET_BYTES = 1_450_000;
/** A sentence is kept while one of its words is in fewer kept sentences than this. */
const SENTENCES_PER_WORD = 12;

/** The tag Tatoeba puts on a sentence whose Chinese is not checked yet. */
const NEEDS_NATIVE_CHECK = '@needs native check';

const CHINESE_ONLY = /^[\p{Script=Han}0-9０-９，。！？、；：“”‘’（）《》…—·「」『』]+$/u;
const HAN = /\p{Script=Han}/u;
const NUMBER = /^[一二两三四五六七八九十百千万几0-9]+$/;

interface Row {
  id: number;
  text: string;
  author: string;
}

interface Candidate {
  row: Row;
  simplified: string;
  words: string[];
  contentWords: string[];
  translation: { lang: 'fr' | 'en'; row: Row };
}

interface Counts {
  read: number;
  tooLong: number;
  notChineseOnly: number;
  duplicate: number;
  blockedTag: number;
  maintenanceTag: number;
  needsNativeCheck: number;
  blockedWord: number;
  noTranslation: number;
  blockedTranslation: number;
  tooHard: number;
  overQuota: number;
  kept: number;
}

function sha256(content: Buffer): string {
  return createHash('sha256').update(content).digest('hex');
}

function main(): void {
  const [sourceFolder, outFolder = path.join('public', 'data')] = process.argv.slice(2);
  if (sourceFolder === undefined) {
    throw new Error('Usage: node scripts/sentences/buildSentenceData.ts <sources> [out]');
  }
  const read = (file: string) =>
    // eslint-disable-next-line security/detect-non-literal-fs-filename -- listed sources only
    readFileSync(path.join(sourceFolder, file));
  const text = (file: string) => read(file).toString('utf8');
  const lines = (file: string) =>
    text(file)
      .split('\n')
      .filter((line) => line !== '' && !line.startsWith('#'))
      .map((line) => line.split('\t'));
  const hashes = SOURCES.map(({ file, url }) => ({ file, url, sha256: sha256(read(file)) }));

  // --- HSK words: level (1 to 6) and part-of-speech tags; meanings and classifiers left out.
  const hsk = new Map<string, { level: number; pos: string[] }>();
  for (const level of [1, 2, 3, 4, 5, 6]) {
    const words = JSON.parse(text(`hsk${String(level)}.json`)) as { s: string; p: string[] }[];
    for (const { s, p } of words) {
      if (!hsk.has(s)) {
        hsk.set(s, { level, pos: [...p].sort() });
      }
    }
  }
  const upToLevel = (max: number) =>
    new Set([...hsk].filter(([, { level }]) => level <= max).map(([word]) => word));
  const hsk4 = upToLevel(4);

  // --- Measure words of the HSK nouns, from the CL: field of CC-CEDICT.
  const cedictDate = /^#! date=(\d{4}-\d{2}-\d{2})/m.exec(text('cedict.txt'))?.[1] ?? 'unknown';
  const measureWords = new Map<string, Set<string>>();
  for (const line of text('cedict.txt').split('\n')) {
    const entry = /^\S+ (\S+) \[[^\]]*\] \/(.*)\/\s*$/.exec(line);
    const word = entry?.[1];
    const found = /CL:([^/]*)/.exec(entry?.[2] ?? '');
    const pos = word === undefined ? undefined : hsk.get(word)?.pos;
    if (word === undefined || found?.[1] === undefined || pos === undefined || !isNoun(pos)) {
      continue;
    }
    const set = measureWords.get(word) ?? new Set<string>();
    for (const part of found[1].split(',')) {
      // 個|个[ge4] or 个[ge4]: the simplified form is the one just before the brackets.
      const classifier = /([^|[]+)\[/.exec(part.trim())?.[1];
      if (classifier !== undefined && HAN.test(classifier) && Array.from(classifier).length <= 2) {
        set.add(classifier);
      }
    }
    if (set.size > 0) {
      measureWords.set(word, set);
    }
  }

  // --- Tatoeba.
  const tagsOf = (files: readonly string[]) => {
    const tags = new Map<number, Set<string>>();
    for (const file of files) {
      for (const [id, tag] of lines(file)) {
        const set = tags.get(Number(id)) ?? new Set<string>();
        set.add((tag ?? '').trim().toLowerCase());
        tags.set(Number(id), set);
      }
    }
    return tags;
  };
  const tags = tagsOf(['cmn_tags.tsv', 'fra_tags.tsv', 'eng_tags.tsv']);
  const blockedByTag = (id: number) =>
    [...(tags.get(id) ?? [])].some(
      (tag) => !tag.startsWith(MAINTENANCE_TAG_PREFIX) && isBlockedTag(tag),
    );
  const maintained = (id: number) =>
    [...(tags.get(id) ?? [])].some((tag) => tag.startsWith(MAINTENANCE_TAG_PREFIX));
  const cc0 = new Set(lines('cmn_sentences_CC0.tsv').map(([id]) => Number(id)));
  const rowsOf = (file: string) =>
    new Map(
      lines(file).map(([id, , sentence, user]) => [
        Number(id),
        {
          id: Number(id),
          text: (sentence ?? '').trim(),
          author: user === undefined || user === '\\N' || user === '' ? ANONYMOUS : user,
        },
      ]),
    );
  const french = rowsOf('fra_sentences_detailed.tsv');
  const english = rowsOf('eng_sentences_detailed.tsv');
  const translationsOf = (file: string, rows: Map<number, Row>) => {
    const links = new Map<number, Row[]>();
    for (const [from, to] of lines(file)) {
      const row = rows.get(Number(to));
      if (row !== undefined) {
        links.set(Number(from), [...(links.get(Number(from)) ?? []), row]);
      }
    }
    return links;
  };
  const toFrench = translationsOf('cmn-fra_links.tsv', french);
  const toEnglish = translationsOf('cmn-eng_links.tsv', english);
  const offensive = (row: Row) => blockedByTag(row.id) || isBlockedTranslation(row.text);
  const usable = (row: Row) => !maintained(row.id) && row.text.length <= 200;
  /**
   * French first, then the oldest translation (lowest id): a fixed choice. Strict: one
   * offensive translation, in any of the two languages, leaves the sentence out.
   */
  const translationOf = (id: number): { lang: 'fr' | 'en'; row: Row } | 'blocked' | undefined => {
    const all = [
      ...(toFrench.get(id) ?? []).map((row) => ({ lang: 'fr' as const, row })),
      ...(toEnglish.get(id) ?? []).map((row) => ({ lang: 'en' as const, row })),
    ];
    if (all.some(({ row }) => offensive(row))) {
      return 'blocked';
    }
    return all
      .filter(({ row }) => usable(row))
      .sort((a, b) => (a.lang === b.lang ? a.row.id - b.row.id : a.lang === 'fr' ? -1 : 1))[0];
  };

  const toSimplified = OpenCC.Converter({ from: 'tw', to: 'cn' });
  const segmenter = new Intl.Segmenter('zh', { granularity: 'word' });
  const counts: Counts = {
    read: 0,
    tooLong: 0,
    notChineseOnly: 0,
    duplicate: 0,
    blockedTag: 0,
    maintenanceTag: 0,
    needsNativeCheck: 0,
    blockedWord: 0,
    noTranslation: 0,
    blockedTranslation: 0,
    tooHard: 0,
    overQuota: 0,
    kept: 0,
  };
  const seen = new Set<string>();
  const authors = new Map<string, number>([[ANONYMOUS, 0]]);
  const authorIndex = (name: string) => {
    if (!authors.has(name)) {
      authors.set(name, authors.size);
    }
    return authors.get(name) ?? 0;
  };
  const entries: unknown[][] = [];
  const candidates: Candidate[] = [];
  const chinese = [...rowsOf('cmn_sentences_detailed.tsv').values()].sort((a, b) => a.id - b.id);
  for (const row of chinese) {
    counts.read += 1;
    const simplified = toSimplified(row.text).trim();
    const sentenceTags = tags.get(row.id) ?? new Set<string>();
    if (Array.from(simplified).length > MAX_CHARS) {
      counts.tooLong += 1;
    } else if (!CHINESE_ONLY.test(simplified) || !HAN.test(simplified)) {
      counts.notChineseOnly += 1;
    } else if (seen.has(simplified)) {
      counts.duplicate += 1;
    } else if (blockedByTag(row.id)) {
      counts.blockedTag += 1;
    } else if (sentenceTags.has(NEEDS_NATIVE_CHECK)) {
      counts.needsNativeCheck += 1;
    } else if (maintained(row.id)) {
      counts.maintenanceTag += 1;
    } else if (isBlockedChinese(simplified)) {
      counts.blockedWord += 1;
    } else {
      const translation = translationOf(row.id);
      const words = Array.from(segmenter.segment(simplified), ({ segment }) => segment).filter(
        (segment) => segment.trim() !== '',
      );
      const outside = words.filter(
        (word) => HAN.test(word) && !NUMBER.test(word) && !splitsInto(word, hsk4),
      );
      if (translation === undefined) {
        counts.noTranslation += 1;
      } else if (translation === 'blocked') {
        counts.blockedTranslation += 1;
      } else if (outside.length > MAX_WORDS_OUTSIDE_HSK4) {
        counts.tooHard += 1;
      } else {
        seen.add(simplified);
        candidates.push({
          row,
          simplified,
          words,
          translation,
          contentWords: [...new Set(words.filter((word) => HAN.test(word) && !NUMBER.test(word)))],
        });
      }
    }
  }

  // Many sentences repeat the same common words. Easiest first (fewest words outside HSK 1-3,
  // then shortest), a sentence is kept while one of its words is in fewer than
  // SENTENCES_PER_WORD kept sentences, until the size budget is spent.
  const hsk3 = upToLevel(3);
  const selected = selectEasiest(candidates, hsk3);
  counts.overQuota = candidates.length - selected.length;
  counts.kept = selected.length;
  for (const { row, words, translation, simplified } of selected) {
    const flags = {
      ...(simplified === row.text ? {} : { t2s: true }),
      ...(cc0.has(row.id) ? { license: 'CC0-1.0' } : {}),
    };
    entries.push([
      row.id,
      authorIndex(row.author),
      words.join(' '),
      translation.lang,
      translation.row.id,
      authorIndex(translation.row.author),
      translation.row.text,
      ...(Object.keys(flags).length === 0 ? [] : [flags]),
    ]);
  }

  const exportDate = process.env.TATOEBA_EXPORT_DATE ?? 'unknown';
  const sentences = {
    _meta: {
      source: `Tatoeba (https://tatoeba.org), exports from ${TATOEBA}/ dated ${exportDate}`,
      license:
        'CC-BY-2.0-FR (https://creativecommons.org/licenses/by/2.0/fr/); entries with "license": "CC0-1.0" are also available under CC0 1.0 (https://creativecommons.org/publicdomain/zero/1.0/)',
      attribution:
        'Each sentence and translation is by the Tatoeba contributor named in its "author" field (an index into "authors"); sentence page: https://tatoeba.org/sentences/show/<id>',
      changes:
        'Selection of sentences; entries with "t2s": true were converted from traditional to simplified characters with opencc-js. Text otherwise unchanged.',
      notice: 'This data is not covered by the PolyForm Noncommercial License of vocab-learner.',
      fields:
        'sentences: [id, author, words separated by spaces, translation language, translation id, translation author, translation, {t2s, license}?]',
    },
    format: 'vocab-learner-sentences',
    version: 1,
    authors: [...authors.keys()],
    sentences: entries,
  };
  const measure = {
    _meta: {
      source: `CC-CEDICT, published by MDBG (https://www.mdbg.net/chinese/dictionary?page=cc-cedict), release dated ${cedictDate}; based on CEDICT, Copyright (C) 1997, 1998 Paul Andrew Denisowski`,
      license: 'CC-BY-SA-4.0 (https://creativecommons.org/licenses/by-sa/4.0/)',
      changes:
        'Adapted by vocab-learner: only the measure words (CL:) of HSK nouns were extracted and converted to JSON; definitions were removed.',
      notice:
        'This adapted data is licensed under CC BY-SA 4.0, not under the PolyForm Noncommercial License of vocab-learner.',
    },
    format: 'vocab-learner-measure-words',
    version: 1,
    nouns: Object.fromEntries(
      [...measureWords]
        .sort(([a], [b]) => compare(a, b))
        .map(([noun, set]) => [noun, [...set].sort(compare)]),
    ),
  };
  const hskWords = {
    _meta: {
      source: `complete-hsk-vocabulary (${HSK_REPOSITORY}), commit ${HSK_COMMIT}; part-of-speech tags from SUBTLEX-CH (Cai & Brysbaert, 2010) and HanLP, as stated by that project`,
      license:
        'MIT, Copyright (c) 2026 Yanis Zafirópulos (aka Dr.Kameleon); full text in THIRD_PARTY_LICENSES',
      changes:
        'Only words, HSK levels and part-of-speech tags kept; CC-CEDICT meanings and classifiers removed.',
      fields: 'words: { word: [HSK level 1-6, part-of-speech tags separated by spaces] }',
    },
    format: 'vocab-learner-hsk-words',
    version: 1,
    words: Object.fromEntries(
      [...hsk]
        .sort(([a], [b]) => compare(a, b))
        .map(([word, { level, pos }]) => [word, [level, pos.join(' ')]]),
    ),
  };
  const write = (file: string, data: unknown) => {
    const content = `${JSON.stringify(data)}\n`;
    // eslint-disable-next-line security/detect-non-literal-fs-filename -- fixed output names
    writeFileSync(path.join(outFolder, file), content);
    return { file, bytes: Buffer.byteLength(content), sha256: sha256(Buffer.from(content)) };
  };
  const outputs = [
    write('sentences-zh.json', sentences),
    write('measure-words.json', measure),
    write('hsk-words.json', hskWords),
  ];
  // eslint-disable-next-line security/detect-non-literal-fs-filename -- fixed output name
  writeFileSync(
    path.join(outFolder, 'README.md'),
    readme({ hashes, outputs, counts, exportDate, cedictDate, nouns: measureWords.size }),
  );
  console.log(JSON.stringify({ counts, outputs, authors: authors.size }, null, 2));
}

/**
 * Easiest first: no or one word outside HSK 1-3 (the word asked), then two, then more; shorter
 * first, then by id. Kept while it brings a word under the quota and the budget is not spent.
 */
function selectEasiest(candidates: readonly Candidate[], hsk3: ReadonlySet<string>): Candidate[] {
  const tier = ({ contentWords }: Candidate) =>
    Math.max(1, contentWords.filter((word) => !splitsInto(word, hsk3)).length);
  const length = ({ simplified }: Candidate) => Array.from(simplified).length;
  const ordered = candidates
    .map((candidate) => ({ candidate, tier: tier(candidate), length: length(candidate) }))
    .sort(
      (a, b) => a.tier - b.tier || a.length - b.length || a.candidate.row.id - b.candidate.row.id,
    )
    .map(({ candidate }) => candidate);
  const seen = new Map<string, number>();
  const kept: Candidate[] = [];
  let bytes = 0;
  for (const candidate of ordered) {
    const { contentWords } = candidate;
    const size = estimateBytes([candidate]);
    if (
      bytes + size > TARGET_BYTES ||
      !contentWords.some((word) => (seen.get(word) ?? 0) < SENTENCES_PER_WORD)
    ) {
      continue;
    }
    bytes += size;
    kept.push(candidate);
    for (const word of contentWords) {
      seen.set(word, (seen.get(word) ?? 0) + 1);
    }
  }
  return kept.sort((a, b) => a.row.id - b.row.id);
}

/** About the bytes of the entries in the file: UTF-8 text plus the numbers and punctuation. */
function estimateBytes(selected: readonly Candidate[]): number {
  return selected.reduce(
    (total, { row, words, translation }) =>
      total +
      Buffer.byteLength(
        JSON.stringify([
          row.id,
          0,
          words.join(' '),
          'fr',
          translation.row.id,
          0,
          translation.row.text,
        ]),
      ) +
      // Author indices of up to 4 digits, the comma, and now and then the flags.
      8,
    0,
  );
}

function isNoun(pos: readonly string[]): boolean {
  return pos.some((tag) => tag === 'n' || tag === 'nr' || tag === 'nz' || tag === 'ng');
}

/** Code point order: the same on every machine, unlike a locale order. */
function compare(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

/** Whether a word splits into known words, longest first (去睡觉 → 去 + 睡觉). */
function splitsInto(word: string, known: ReadonlySet<string>): boolean {
  if (word === '') {
    return true;
  }
  const chars = Array.from(word);
  for (let length = Math.min(4, chars.length); length > 0; length--) {
    if (
      known.has(chars.slice(0, length).join('')) &&
      splitsInto(chars.slice(length).join(''), known)
    ) {
      return true;
    }
  }
  return false;
}

interface ReadmeInput {
  hashes: { file: string; url: string; sha256: string }[];
  outputs: { file: string; bytes: number; sha256: string }[];
  counts: Counts;
  exportDate: string;
  cedictDate: string;
  nouns: number;
}

function readme({ hashes, outputs, counts, exportDate, cedictDate, nouns }: ReadmeInput): string {
  const rows = (items: string[][]) => items.map((cells) => `| ${cells.join(' | ')} |`).join('\n');
  return `# Sentence data (generated, do not edit)

These files are generated by \`scripts/sentences/buildSentenceData.ts\` and keep their own
licenses: they are **not** covered by the PolyForm Noncommercial License of vocab-learner. See
THIRD_PARTY_LICENSES.

| File | Data | License |
|---|---|---|
| sentences-zh.json | Tatoeba sentences (each with its author) | CC BY 2.0 FR, some CC0 1.0 |
| measure-words.json | Measure words of the HSK nouns, adapted from CC-CEDICT | CC BY-SA 4.0 |
| hsk-words.json | HSK 1-6 words with their level and part-of-speech tags | MIT |

## Inputs

Tatoeba exports dated ${exportDate}; CC-CEDICT release dated ${cedictDate};
complete-hsk-vocabulary commit ${HSK_COMMIT}.
Generated with Node ${process.version} (ICU ${process.versions.icu ?? 'unknown'}), whose
Intl.Segmenter cuts the sentences into words.

| File | URL | SHA-256 |
|---|---|---|
${rows(hashes.map(({ file, url, sha256: hash }) => [file, url, hash]))}

The .bz2 and .gz downloads are decompressed first; the SHA-256 are those of the decompressed
files.

## Outputs

| File | Bytes | SHA-256 |
|---|---|---|
${rows(outputs.map(({ file, bytes, sha256: hash }) => [file, String(bytes), hash]))}

${String(nouns)} HSK nouns have a measure word.

## Sentence filters

Chinese sentences of at most ${String(MAX_CHARS)} characters, in Han characters, digits and
punctuation only, with a French (else English) translation, and at most
${String(MAX_WORDS_OUTSIDE_HSK4)} words outside HSK 1-4. Then, easiest first (fewest words outside
HSK 1-3, then shortest), a sentence is kept while one of its words appears in fewer than
${String(SENTENCES_PER_WORD)} kept sentences, until the bank reaches about ${String(TARGET_BYTES)}
bytes ("overQuota" below). The learner is a minor: sentences
tagged as offensive, vulgar, sexual, violent or about drugs on Tatoeba (in any of the three
languages), or holding a word of the blocklist of the script, are left out; so are sentences
tagged "@needs native check" or with another maintenance tag ("@change", "@delete"...).

| Step | Sentences |
|---|---|
${rows(Object.entries(counts).map(([step, count]) => [step, String(count)]))}
`;
}

main();
